macro_rules! deps {
    () => {
        Mask!();
        MoveMask!();
    };
}

macro_rules! Vector {
    () => {
        deps!();
        # [doc = " A trait for describing vector operations used by vectorized searchers."] # [doc = ""] # [doc = " The trait is highly constrained to low level vector operations needed."] # [doc = " In general, it was invented mostly to be generic over x86's __m128i and"] # [doc = " __m256i types. At time of writing, it also supports wasm and aarch64"] # [doc = " 128-bit vector types as well."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " All methods are not safe since they are intended to be implemented using"] # [doc = " vendor intrinsics, which are also not safe. Callers must ensure that the"] # [doc = " appropriate target features are enabled in the calling function, and that"] # [doc = " the current CPU supports them. All implementations should avoid marking the"] # [doc = " routines with #[target_feature] and instead mark them as #[inline(always)]"] # [doc = " to ensure they get appropriately inlined. (inline(always) cannot be used"] # [doc = " with target_feature.)"] pub (crate) trait Vector : Copy + core :: fmt :: Debug { # [doc = " The number of bytes in the vector. That is, this is the size of the"] # [doc = " vector in memory."] const BYTES : usize ; # [doc = " The bits that must be zero in order for a `*const u8` pointer to be"] # [doc = " correctly aligned to read vector values."] const ALIGN : usize ; # [doc = " The type of the value returned by `Vector::movemask`."] # [doc = ""] # [doc = " This supports abstracting over the specific representation used in"] # [doc = " order to accommodate different representations in different ISAs."] type Mask : MoveMask ; # [doc = " Create a vector with 8-bit lanes with the given byte repeated into each"] # [doc = " lane."] unsafe fn splat (byte : u8) -> Self ; # [doc = " Read a vector-size number of bytes from the given pointer. The pointer"] # [doc = " must be aligned to the size of the vector."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Callers must guarantee that at least `BYTES` bytes are readable from"] # [doc = " `data` and that `data` is aligned to a `BYTES` boundary."] unsafe fn load_aligned (data : * const u8) -> Self ; # [doc = " Read a vector-size number of bytes from the given pointer. The pointer"] # [doc = " does not need to be aligned."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Callers must guarantee that at least `BYTES` bytes are readable from"] # [doc = " `data`."] unsafe fn load_unaligned (data : * const u8) -> Self ; # [doc = " _mm_movemask_epi8 or _mm256_movemask_epi8"] unsafe fn movemask (self) -> Self :: Mask ; # [doc = " _mm_cmpeq_epi8 or _mm256_cmpeq_epi8"] unsafe fn cmpeq (self , vector2 : Self) -> Self ; # [doc = " _mm_and_si128 or _mm256_and_si256"] unsafe fn and (self , vector2 : Self) -> Self ; # [doc = " _mm_or or _mm256_or_si256"] unsafe fn or (self , vector2 : Self) -> Self ; # [doc = " Returns true if and only if `Self::movemask` would return a mask that"] # [doc = " contains at least one non-zero bit."] unsafe fn movemask_will_have_non_zero (self) -> bool { self . movemask () . has_non_zero () } }
    };
}

Vector!();